#ifndef __NEMC_H__
#define __NEMC_H__


#include <common.h>


/*
[Nomal read]

                 _____     _____     _____     _____      _____     _____     _____     _____
CLK(300M)    ___/     \___/     \___/     \___/     \____/     \___/     \___/     \___/     \

       _________                                          ___________________________________
CS(out)         \________________________________________/

                 ________________________________________
ADDR(out)_______/                                        \_____________________________________
                \________________________________________/
                +         +                    +         +
                |         |                    |         |
                |<- TAS ->|                    |<- TAH- >|
                |         |                    |         |
                +         +                    +         +
        __________________                     _________________________________________________
RD(out)                   \___________________/

                           +         +
                           |         |
                           |<- TAW- >|
                           |         |
                           +         +
                                      ________
    _________________________________/        \_________________________________________________
DATA                                 \________/

                            _________
WAIT_______________________/         \__________________________________________________________


[Nomal write]

                 _____     _____     _____     _____      _____     _____     _____     _____
CLK(300M)    ___/     \___/     \___/     \___/     \____/     \___/     \___/     \___/     \

  ______________                                                    ___________________________________
CS(out)         \__________________________________________________/

                 __________________________________________________
ADDR(out)_______/                                                  \________________________________________
                \__________________________________________________/
                 +         +                             +         +
                 |         |                             |         |
                 |<- TAS ->|                             |<- TAH- >|
                 |         |                             |         |
                 +         +                             +         +
   _________________________________                     _________________________________________________
WE                                  \___________________/

                                    +         +
                                    |         |
                                    |<- TBP- >|
                                    |         |
                                    +         +
                                               ________
    __________________________________________/        \_________________________________________________
DATA                                          \________/

                                      _________
WAIT_________________________________/         \__________________________________________________________


*/

struct nemc_timing {
    uint32_t tas;               /* Tas */
    uint32_t taw;               /* Taw */
    uint32_t tbp;               /* Tbp */
    uint32_t tah;               /* Tah */
    uint32_t strv;              /* strv */
};

void *nemc_get_addr(int id);
void nemc_get_timing(int id, struct nemc_timing *timing);
void nemc_set_timing(int id, struct nemc_timing *timing);

#endif